#!/usr/bin/env bash
# Starts the Nexus of docker-compose.yml, waits until it accepts writes and writes a Maven settings.xml with the
# admin credentials for the server ids of distributionManagement (nexus-releases, nexus-snapshots).
# Prints the settings path. In GitHub Actions it also exports NEXUS_URL, NEXUS_SETTINGS, NEXUS_USER and
# NEXUS_PASSWORD (masked) to the next steps.
# Usage: nexus-up.sh [settings-file]   default: $RUNNER_TEMP/nexus-settings.xml, or target/nexus-settings.xml locally
# Env:   NEXUS_URL (http://localhost:8081), NEXUS_TIMEOUT seconds (300), NEXUS_PASSWORD when the generated
#        admin.password no longer exists (password changed in the UI), NEXUS_ACCEPT_EULA=true to accept the
#        Sonatype Nexus Community Edition EULA (required before the first upload)
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
nexus_url="${NEXUS_URL:-http://localhost:8081}"
timeout="${NEXUS_TIMEOUT:-300}"
if [[ -n "${RUNNER_TEMP:-}" ]]; then
  settings="${1:-$RUNNER_TEMP/nexus-settings.xml}"
else
  settings="${1:-$repo_root/target/nexus-settings.xml}"
fi
compose=(docker compose -f "$repo_root/docker-compose.yml")

"${compose[@]}" up -d nexus >&2

echo "Waiting for $nexus_url/service/rest/v1/status/writable (timeout ${timeout}s)" >&2
deadline=$((SECONDS + timeout))
until curl -fs -o /dev/null "$nexus_url/service/rest/v1/status/writable"; do
  if ((SECONDS >= deadline)); then
    "${compose[@]}" logs --tail 50 nexus >&2
    echo "Nexus is not writable after ${timeout}s" >&2
    exit 1
  fi
  sleep 5
done
echo "Nexus is writable after ${SECONDS}s" >&2

password="${NEXUS_PASSWORD:-}"
if [[ -z "$password" ]]; then
  if ! password="$("${compose[@]}" exec -T nexus cat /nexus-data/admin.password 2>/dev/null)"; then
    echo "/nexus-data/admin.password not found (password already changed): set NEXUS_PASSWORD" >&2
    exit 1
  fi
fi

# Community Edition rejects uploads (HTTP 403) until its EULA is accepted; acceptance is an explicit opt-in
eula_url="$nexus_url/service/rest/v1/system/eula"
eula="$(curl -fsS -u "admin:${password}" "$eula_url")"
if [[ "$(jq -r '.accepted' <<< "$eula")" != "true" ]]; then
  if [[ "${NEXUS_ACCEPT_EULA:-false}" != "true" ]]; then
    echo "Nexus Community Edition requires accepting its EULA (https://links.sonatype.com/products/nxrm/ce-eula)." >&2
    echo "Set NEXUS_ACCEPT_EULA=true to accept it through $eula_url" >&2
    exit 1
  fi
  jq '.accepted = true' <<< "$eula" |
    curl -fsS -o /dev/null -u "admin:${password}" -H 'Content-Type: application/json' -X POST --data @- "$eula_url"
  echo "Nexus EULA accepted (NEXUS_ACCEPT_EULA=true)" >&2
fi

mkdir -p "$(dirname "$settings")"
servers=""
for id in nexus-releases nexus-snapshots; do
  servers+="    <server><id>${id}</id><username>admin</username><password>${password}</password></server>"$'\n'
done
cat > "$settings" <<XML
<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by .github/scripts/nexus-up.sh for the local Nexus. Never commit it. -->
<settings xmlns="http://maven.apache.org/SETTINGS/1.2.0">
  <servers>
${servers}  </servers>
</settings>
XML
chmod 600 "$settings"

if [[ -n "${GITHUB_ENV:-}" ]]; then
  echo "::add-mask::${password}"
  {
    echo "NEXUS_URL=${nexus_url}"
    echo "NEXUS_SETTINGS=${settings}"
    echo "NEXUS_USER=admin"
    echo "NEXUS_PASSWORD=${password}"
  } >> "$GITHUB_ENV"
fi
echo "$settings"
